"""환불 API — `POST /orders/<id>/refund`의 몸."""


class RefundError(Exception):
    pass


def refund(order, amount=None):
    """주문을 환불한다. amount가 없으면 남은 금액 전부, 있으면 그만큼만 돌려준다(부분 환불)."""
    remaining = order["paid"] - order["refunded"]
    if remaining <= 0:
        raise RefundError("이미 전액 환불된 주문입니다")
    refunded = remaining
    order["refunded"] += refunded
    return {"order": order["id"], "refunded": refunded}

import unittest

from refund.service import RefundError, refund


class RefundTest(unittest.TestCase):
    def test_full_refund(self):
        order = {"id": "A-1", "paid": 10000, "refunded": 0}
        self.assertEqual(refund(order), {"order": "A-1", "refunded": 10000})

    def test_refund_twice_is_rejected(self):
        order = {"id": "A-1", "paid": 10000, "refunded": 10000}
        with self.assertRaises(RefundError):
            refund(order)


if __name__ == "__main__":
    unittest.main()

