// 주문 상세의 「환불」 버튼 — 금액을 넣으면 부분 환불, 비우면 전액 환불.
export async function requestRefund(orderId, amount) {
  const body = amount ? { amount } : {};
  const res = await fetch(`/orders/${orderId}/refund`, { method: "POST", body: JSON.stringify(body) });
  return res.json();
}
